# Test strict hint-literal algorithm on raw OCR
import re
import os

PRIORITY_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]
EXCLUDE = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
NUMBER_RE = re.compile(r'\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+\.\d+|\d+')

def extract_total_strict(text):
    lines = text.splitlines()
    for group in PRIORITY_GROUPS:
        for i, line in enumerate(lines):
            upper = line.upper()
            if any(e in upper for e in EXCLUDE):
                continue
            for kw in group:
                if kw in upper:
                    idx = upper.index(kw)
                    after = line[idx + len(kw):]
                    nums = NUMBER_RE.findall(after)
                    if nums:
                        n = nums[-1].replace(',', '')
                        try:
                            v = float(n)
                            if v > 0:
                                return f"{v:.2f}"
                        except ValueError:
                            pass
                    # fallback next line
                    for j in range(i+1, len(lines)):
                        nxt = lines[j].strip()
                        if not nxt:
                            continue
                        nums2 = NUMBER_RE.findall(nxt)
                        if nums2:
                            n = nums2[-1].replace(',', '')
                            try:
                                v = float(n)
                                if v > 0:
                                    return f"{v:.2f}"
                            except ValueError:
                                pass
                        break
                    return None
    return None

def extract_date_strict(text):
    month_map = {'jan':1,'feb':2,'mar':3,'apr':4,'may':5,'jun':6,'jul':7,'aug':8,'sep':9,'oct':10,'nov':11,'dec':12}
    patterns = [
        (r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b', 'dmy'),
        (r'\b(\d{1,2})[\s\-]+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[\s\-,]+(\d{4})\b', 'dmony'),
        (r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b', 'dmy2'),
    ]
    for pat, kind in patterns:
        for m in re.finditer(pat, text, re.IGNORECASE):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmony':
                    d = int(m.group(1)); mo = month_map[m.group(2).lower()]; y = int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 70 else 1900 + y
                if 1 <= mo <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
                    return f"{y:04d}-{mo:02d}-{d:02d}"
            except (KeyError, ValueError):
                continue
    return None

for f in sorted(os.listdir('/app/workspace/ocr_cache/')):
    with open(f'/app/workspace/ocr_cache/{f}') as fh:
        txt = fh.read()
    name = f.replace('.png.txt', '.png')
    print(f"{name}: date={extract_date_strict(txt)}, total={extract_total_strict(txt)}")
