import re
import os

def extract_date(text):
    """Extract first plausible date and return ISO format."""
    # DD/MM/YYYY, D/M/YYYY, DD-MM-YYYY
    # Try full-year first
    patterns = [
        # DD/MM/YYYY with slashes or hyphens
        (r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b', 'dmy'),
        (r'\b(\d{4})[/\-](\d{1,2})[/\-](\d{1,2})\b', 'ymd'),
        # DD Mon YYYY e.g., "08 Jan 2017"
        (r'\b(\d{1,2})[\s\-]+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[\s\-,]+(\d{4})\b', 'dmony'),
        # DD/MM/YY (2-digit year)
        (r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b', 'dmy2'),
    ]
    month_map = {'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}

    for pat, kind in patterns:
        m = re.search(pat, text, re.IGNORECASE)
        if m:
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmony':
                    d = int(m.group(1)); mo = month_map[m.group(2).capitalize()]; y = int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 50 else 1900 + y
                if not (1 <= mo <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099):
                    continue
                return f"{y:04d}-{mo:02d}-{d:02d}"
            except (KeyError, ValueError):
                continue
    return None


# Priority keyword groups
PRIORITY_GROUPS = [
    [r'GRAND\s*TOTAL'],
    [r'TOTAL\s*:?\s*RM'],
    [r'TOTAL\s*AMOUNT'],
    [r'TOTAL\s*DUE', r'AMOUNT\s*DUE', r'BALANCE\s*DUE', r'NETT\s*TOTAL', r'NET\s*TOTAL', r'\bTOTAL\b', r'\bAMOUNT\b'],
]

EXCLUDE = [r'SUBTOTAL', r'SUB\s*TOTAL', r'\bTAX\b', r'\bGST\b', r'\bSST\b', r'DISCOUNT', r'CHANGE', r'CASH\s*TENDERED']

def find_last_number(line):
    """Find the last number (possibly with comma separator and decimal) in a line."""
    # Match numbers like 1,234.56 or 123.45 or 123 with optional trailing letters/chars
    nums = re.findall(r'(\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+\.\d+|\d+)', line)
    # Filter reasonable amounts (prefer those with a decimal point)
    return nums

def normalize_amount(s):
    s = s.replace(',', '')
    try:
        v = float(s)
        return f"{v:.2f}"
    except ValueError:
        return None

def is_excluded(line):
    for pat in EXCLUDE:
        if re.search(pat, line, re.IGNORECASE):
            return True
    return False

def extract_total(text):
    lines = text.splitlines()
    for group in PRIORITY_GROUPS:
        for i, line in enumerate(lines):
            if is_excluded(line):
                continue
            for pat in group:
                if re.search(pat, line, re.IGNORECASE):
                    # Try to get the last number on this line (after the keyword)
                    m = re.search(pat, line, re.IGNORECASE)
                    after = line[m.end():]
                    nums = find_last_number(after)
                    # Filter to prefer numeric with decimal
                    decimal_nums = [n for n in nums if '.' in n]
                    if decimal_nums:
                        return normalize_amount(decimal_nums[-1])
                    # If no number after, check next line
                    if i + 1 < len(lines):
                        nums = find_last_number(lines[i+1])
                        decimal_nums = [n for n in nums if '.' in n]
                        if decimal_nums:
                            return normalize_amount(decimal_nums[-1])
                        if nums:
                            return normalize_amount(nums[-1])
                    # Fallback: integers on the line
                    if nums:
                        return normalize_amount(nums[-1])
    return None


files = sorted(os.listdir('/app/workspace/ocr_cache/'))
for f in files:
    with open(f'/app/workspace/ocr_cache/{f}') as fh:
        txt = fh.read()
    name = f.replace('.txt', '')
    date = extract_date(txt)
    total = extract_total(txt)
    print(f"{name}: date={date}, total={total}")
