        # DD/MM/YY (2-digit year)
        (r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b', 'dmy2'),
    ]
    month_map = {'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}

    for pat, kind in patterns:
        m = re.search(pat, text, re.IGNORECASE)
        if m:
