import os
import re
import pytesseract
from PIL import Image, ImageFilter
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

MONTH_MAP = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun',
     'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}

DATE_PATTERNS = [
    # DD/MM/YYYY or DD-MM-YYYY
    (r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b', 'dmy'),
    # YYYY-MM-DD
    (r'\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b', 'ymd'),
    # DD Mon YYYY (e.g. "08 Jan 2017")
    (r'\b(\d{1,2})[\s\-]+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[\s\-,]+(\d{4})\b', 'dmony'),
    # DDMM/YYYY (OCR missed slash) e.g., "1202/2018"
    (r'\b(\d{2})(\d{2})/(\d{4})\b', 'dmy'),
    # DD/MM/YY
    (r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b', 'dmy2'),
]

# Priority groups of keyword patterns (highest priority first)
PRIORITY_GROUPS = [
    [r'GRAND\s*TOTAL'],
    [r'TOTAL\s*:?\s*RM', r'TOTAL\s*RM'],
    [r'TOTAL\s*AMOUNT'],
    [r'TOTAL\s*DUE', r'AMOUNT\s*DUE', r'BALANCE\s*DUE',
     r'NETT\s*TOTAL', r'NET\s*TOTAL'],
    [r'\bTOTAL\b'],
    [r'\bAMOUNT\b'],
]

EXCLUDE_PATS = [
    r'SUBTOTAL', r'SUB\s*TOTAL',
    r'\bTAX\b', r'\bGST\b', r'\bSST\b',
    r'DISCOUNT', r'CHANGE', r'CASH\s*TENDERED',
]

NUMBER_RE = re.compile(r'\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+\.\d+|\d+')


def normalize_spaces_in_decimals(line):
    """Fix OCR artefacts like "14. 65" -> "14.65" and "14 .65" -> "14.65"."""
    return re.sub(r'(\d)\s*\.\s*(\d)', r'\1.\2', line)


def extract_date(text):
    for pat, kind in DATE_PATTERNS:
        for m in re.finditer(pat, text, re.IGNORECASE):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmony':
                    d = int(m.group(1))
                    mo = MONTH_MAP[m.group(2).lower()]
                    y = int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 70 else 1900 + y
                if 1 <= mo <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099:
                    return f"{y:04d}-{mo:02d}-{d:02d}"
            except (KeyError, ValueError):
                continue
    return None


def is_excluded(line):
    for pat in EXCLUDE_PATS:
        if re.search(pat, line, re.IGNORECASE):
            return True
    return False


def normalize_amount(s):
    s = s.replace(',', '')
    try:
        v = float(s)
        if v <= 0:
            return None
        return f"{v:.2f}"
    except ValueError:
        return None


def pick_amount_from_line(after_text):
    """Return best amount candidate from the segment after keyword."""
    after_text = normalize_spaces_in_decimals(after_text)
    nums = NUMBER_RE.findall(after_text)
    decimal_nums = [n for n in nums if '.' in n]
    if decimal_nums:
        return normalize_amount(decimal_nums[-1])
    if nums:
        return normalize_amount(nums[-1])
    return None


def pick_amount_from_next_line(line):
    """Return last number from a line (same as hint fallback)."""
    line = normalize_spaces_in_decimals(line)
    nums = NUMBER_RE.findall(line)
    if not nums:
        return None
    decimal_nums = [n for n in nums if '.' in n]
    if decimal_nums:
        return normalize_amount(decimal_nums[-1])
    return normalize_amount(nums[-1])


def extract_total(text):
    lines = text.splitlines()
    for group in PRIORITY_GROUPS:
        # Search bottom-up so the actual total near the receipt footer wins
        for i in range(len(lines) - 1, -1, -1):
            line = lines[i]
            if is_excluded(line):
                continue
            for pat in group:
                m = re.search(pat, line, re.IGNORECASE)
                if not m:
                    continue
                after = line[m.end():]
                amt = pick_amount_from_line(after)
                if amt is not None:
                    return amt
                # Fallback: look at next non-empty line
                for j in range(i + 1, len(lines)):
                    nxt = lines[j].strip()
                    if not nxt:
                        continue
                    amt = pick_amount_from_next_line(nxt)
                    if amt is not None:
                        return amt
                    break
    return None


def ocr_variants(img_path):
    """Yield (name, ocr_text) for several OCR preprocessing variants."""
    img = Image.open(img_path).convert('L')
    yield 'raw', pytesseract.image_to_string(img)
    for size in (3, 5, 7):
        yield f'min{size}', pytesseract.image_to_string(
            img.filter(ImageFilter.MinFilter(size=size)))


def extract_one(img_path):
    date = None
    total = None
    for _, text in ocr_variants(img_path):
        if date is None:
            date = extract_date(text)
        if total is None:
            total = extract_total(text)
        if date is not None and total is not None:
            break
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for f in files:
        date, total = extract_one(os.path.join(IMG_DIR, f))
        rows.append((f, date, total))
        print(f"{f}: date={date}, total={total}")

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for row in rows:
        ws.append(list(row))
    wb.save(OUT_PATH)
    print(f"Saved {OUT_PATH}")


if __name__ == '__main__':
    main()
