        (r'\b(\d{1,2})[\s\-]+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[\s\-,]+(\d{4})\b', 'dmony'),
        # DD/MM/YY (2-digit year)
        (r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b', 'dmy2'),
    ]
    month_map = {'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}

    for pat, kind in patterns:
        m = re.search(pat, text, re.IGNORECASE)
        if m:
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmony':
                    d = int(m.group(1)); mo = month_map[m.group(2).capitalize()]; y = int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 50 else 1900 + y
                if not (1 <= mo <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099):
                    continue
                return f"{y:04d}-{mo:02d}-{d:02d}"
            except (KeyError, ValueError):
                continue
    return None


# Priority keyword groups
PRIORITY_GROUPS = [
    [r'GRAND\s*TOTAL'],
    [r'TOTAL\s*:?\s*RM'],
    [r'TOTAL\s*AMOUNT'],
    [r'TOTAL\s*DUE', r'AMOUNT\s*DUE', r'BALANCE\s*DUE', r'NETT\s*TOTAL', r'NET\s*TOTAL', r'\bTOTAL\b', r'\bAMOUNT\b'],
