def extract_date(text):
    """Extract first plausible date and return ISO format."""
    # DD/MM/YYYY, D/M/YYYY, DD-MM-YYYY
    # Try full-year first
    patterns = [
        # DD/MM/YYYY with slashes or hyphens
        (r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b', 'dmy'),
